import{_ as r,a0 as o,w as m,s,ao as d,I as a,x as t,a1 as p,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse(`{"title":"在 Linux 下使用 RAID（三）：用兩塊磁盤創建 RAID 1（鏡像） | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（三）：用兩塊磁盤創建 RAID 1（鏡像） | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（三）：用兩塊磁盤創建 RAID 1（鏡像） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（三）：用兩塊磁盤創建 RAID 1（鏡像） | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 3 - Setting up RAID 1 (Mirroring) using 'Two Disks' in Linux","title":"在 Linux 下使用 RAID（三）：用兩塊磁盤創建 RAID 1（鏡像）","tag":"RAID","desc":""},"relativePath":"RAID/Part 3 - Setting up RAID 1 (Mirroring) using 'Two Disks' in Linux.md","filePath":"[post].md"}`),c={name:"RAID/Part 3 - Setting up RAID 1 (Mirroring) using 'Two Disks' in Linux.md"};function l(D,e,R,A,u,I){const i=o("Link");return m(),s("div",null,[e[15]||(e[15]=d('<h1 id="在-linux-下使用-raid-三-用兩塊磁盤創建-raid-1-鏡像" tabindex="-1">在 Linux 下使用 RAID（三）：用兩塊磁盤創建 RAID 1（鏡像） <a class="header-anchor" href="#在-linux-下使用-raid-三-用兩塊磁盤創建-raid-1-鏡像" aria-label="Permalink to “在 Linux 下使用 RAID（三）：用兩塊磁盤創建 RAID 1（鏡像）”">​</a></h1><p><strong>RAID 鏡像</strong>意味着相同數據的完整克隆（或鏡像），分別寫入到兩個磁盤中。創建 RAID 1 至少需要兩個磁盤，而且僅用於讀取性能或者可靠性要比數據存儲容量更重要的場合。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-RAID1-in-Linux.jpeg" alt="Create Raid1 in Linux"></p><p><em>在 Linux 中設置 RAID 1</em></p><p>創建鏡像是為了防止因硬盤故障導致數據丟失。鏡像中的每個磁盤包含數據的完整副本。當一個磁盤發生故障時，相同的數據可以從其它正常磁盤中讀取。而後，可以從正在運行的計算機中直接更換髮生故障的磁盤，無需任何中斷。</p><h3 id="raid-1-的特點" tabindex="-1">RAID 1 的特點 <a class="header-anchor" href="#raid-1-的特點" aria-label="Permalink to “RAID 1 的特點”">​</a></h3><ul><li><p>鏡像具有良好的性能。</p></li><li><p>磁盤利用率為50％。也就是説，如果我們有兩個磁盤每個500GB，總共是1TB，但在鏡像中它只會顯示500GB。</p></li><li><p>在鏡像如果一個磁盤發生故障不會有數據丟失，因為兩個磁盤中的內容相同。</p></li><li><p>讀取性能會比寫入性能更好。</p></li></ul><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>創建 RAID 1 至少要有兩個磁盤，你也可以添加更多的磁盤，磁盤數需為2，4，6，8等偶數。要添加更多的磁盤，你的系統必須有 RAID 物理適配器（硬件卡）。</p><p>這裏，我們使用軟件 RAID 不是硬件 RAID，如果你的系統有一個內置的物理硬件 RAID 卡，你可以從它的功能界面或使用 Ctrl + I 鍵來訪問它。</p>',10)),a("p",null,[e[1]||(e[1]=t("需要閲讀: ",-1)),p(i,{href:"https://linux.cn/article-6085-1.html"},{default:n(()=>[...e[0]||(e[0]=[t("介紹 RAID 的級別和概念",-1)])]),_:1})]),e[16]||(e[16]=d(`<h4 id="在我的服務器安裝" tabindex="-1">在我的服務器安裝 <a class="header-anchor" href="#在我的服務器安裝" aria-label="Permalink to “在我的服務器安裝”">​</a></h4><pre><code>操作系統 :	CentOS 6.5 Final
IP 地址	 :	192.168.0.226
主機名	 :	rd1.tecmintlocal.com
磁盤 1 [20GB]	 :	/dev/sdb
磁盤 2 [20GB]	 :	/dev/sdc
</code></pre><p>本文將指導你在 Linux 平台上使用 mdadm （用於創建和管理 RAID ）一步步的建立一個軟件 RAID 1 （鏡像）。同樣的做法也適用於如 RedHat，CentOS，Fedora 等 Linux 發行版。</p><h3 id="第1步-安裝所需軟件並且檢查磁盤" tabindex="-1">第1步：安裝所需軟件並且檢查磁盤 <a class="header-anchor" href="#第1步-安裝所需軟件並且檢查磁盤" aria-label="Permalink to “第1步：安裝所需軟件並且檢查磁盤”">​</a></h3><p>1、 正如我前面所説，在 Linux 中我們需要使用 mdadm 軟件來創建和管理 RAID。所以，讓我們用 yum 或 apt-get 的軟件包管理工具在 Linux 上安裝 mdadm 軟件包。</p><pre><code># yum install mdadm		[在 RedHat 系統]
# apt-get install mdadm 	[在 Debain 系統]
</code></pre><p>2、 一旦安裝好<code>mdadm</code>包，我們需要使用下面的命令來檢查磁盤是否已經配置好。</p><pre><code># mdadm -E /dev/sd[b-c]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-on-Disks.png" alt="Check RAID on Disks"></p><p><em>檢查 RAID 的磁盤</em></p><p>正如你從上面圖片看到的，沒有檢測到任何超級塊，這意味着還沒有創建RAID。</p><h3 id="第2步-為-raid-創建分區" tabindex="-1">第2步：為 RAID 創建分區 <a class="header-anchor" href="#第2步-為-raid-創建分區" aria-label="Permalink to “第2步：為 RAID 創建分區”">​</a></h3><p>3、 正如我提到的，我們使用最少的兩個分區 /dev/sdb 和 /dev/sdc 來創建 RAID 1。我們首先使用<code>fdisk</code>命令來創建這兩個分區並更改其類型為 raid。</p><pre><code># fdisk /dev/sdb
</code></pre><p>按照下面的説明</p><ul><li>按 <code>n</code> 創建新的分區。</li><li>然後按 <code>P</code> 選擇主分區。</li><li>接下來選擇分區號為1。</li><li>按兩次回車鍵默認將整個容量分配給它。</li><li>然後，按 <code>P</code> 來打印創建好的分區。</li><li>按 <code>L</code>，列出所有可用的類型。</li><li>按 <code>t</code> 修改分區類型。</li><li>鍵入 <code>fd</code> 設置為 Linux 的 RAID 類型，然後按 Enter 確認。</li><li>然後再次使用<code>p</code>查看我們所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-Disk-Partitions.png" alt="Create Disk Partitions"></p><p><em>創建磁盤分區</em></p><p>在創建“/dev/sdb”分區後，接下來按照同樣的方法創建分區 /dev/sdc 。</p><pre><code># fdisk /dev/sdc
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-Second-Partitions.png" alt="Create Second Partitions"></p><p><em>創建第二個分區</em></p><p>4、 一旦這兩個分區創建成功後，使用相同的命令來檢查 sdb 和 sdc 分區並確認 RAID 分區的類型如上圖所示。</p><pre><code># mdadm -E /dev/sd[b-c]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-Partitions-Changes.png" alt="Verify Partitions Changes"></p><p><em>驗證分區變化</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Type.png" alt="Check RAID Type"></p><p><em>檢查 RAID 類型</em></p><p><strong>注意</strong>: 正如你在上圖所看到的，在 sdb1 和 sdc1 中沒有任何對 RAID 的定義，這就是我們沒有檢測到超級塊的原因。</p><h3 id="第3步-創建-raid-1-設備" tabindex="-1">第3步：創建 RAID 1 設備 <a class="header-anchor" href="#第3步-創建-raid-1-設備" aria-label="Permalink to “第3步：創建 RAID 1 設備”">​</a></h3><p>5、 接下來使用以下命令來創建一個名為 /dev/md0 的“RAID 1”設備並驗證它</p><pre><code># mdadm --create /dev/md0 --level=mirror --raid-devices=2 /dev/sd[b-c]1
# cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-RAID-Device.png" alt="Create RAID Device"></p><p><em>創建RAID設備</em></p><p>6、 接下來使用如下命令來檢查 RAID 設備類型和 RAID 陣列</p><pre><code># mdadm -E /dev/sd[b-c]1
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Device-type.png" alt="Check RAID Device type"></p><p><em>檢查 RAID 設備類型</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Device-Array.png" alt="Check RAID Device Array"></p><p><em>檢查 RAID 設備陣列</em></p><p>從上圖中，人們很容易理解，RAID 1 已經創建好了，使用了 /dev/sdb1 和 /dev/sdc1 分區，你也可以看到狀態為 resyncing（重新同步中）。</p><h3 id="第4步-在-raid-設備上創建文件系統" tabindex="-1">第4步：在 RAID 設備上創建文件系統 <a class="header-anchor" href="#第4步-在-raid-設備上創建文件系統" aria-label="Permalink to “第4步：在 RAID 設備上創建文件系統”">​</a></h3><p>7、 給 md0 上創建 ext4 文件系統</p><pre><code># mkfs.ext4 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-RAID-Device-Filesystem.png" alt="Create RAID Device Filesystem"></p><p><em>創建 RAID 設備文件系統</em></p><p>8、 接下來，掛載新創建的文件系統到“/mnt/raid1”，並創建一些文件，驗證在掛載點的數據</p><pre><code># mkdir /mnt/raid1
# mount /dev/md0 /mnt/raid1/
# touch /mnt/raid1/tecmint.txt
# echo &quot;tecmint raid setups&quot; &gt; /mnt/raid1/tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-RAID-Device.png" alt="Mount Raid Device"></p><p><em>掛載 RAID 設備</em></p><p>9、為了在系統重新啓動自動掛載 RAID 1，需要在 fstab 文件中添加條目。打開<code>/etc/fstab</code>文件並添加以下行：</p><pre><code>/dev/md0                /mnt/raid1              ext4    defaults        0 0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/RAID-Automount-Filesystem.png" alt="Raid Automount Device"></p><p><em>自動掛載 Raid 設備</em></p><p>10、 運行<code>mount -av</code>，檢查 fstab 中的條目是否有錯誤</p><pre><code># mount -av
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Errors-in-fstab.png" alt="Check Errors in fstab"></p><p><em>檢查 fstab 中的錯誤</em></p><p>11、 接下來，使用下面的命令保存 RAID 的配置到文件“mdadm.conf”中。</p><pre><code># mdadm --detail --scan --verbose &gt;&gt; /etc/mdadm.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Save-Raid-Configuration.png" alt="Save Raid Configuration"></p><p><em>保存 Raid 的配置</em></p><p>上述配置文件在系統重啓時會讀取並加載 RAID 設備。</p><h3 id="第5步-在磁盤故障後檢查數據" tabindex="-1">第5步：在磁盤故障後檢查數據 <a class="header-anchor" href="#第5步-在磁盤故障後檢查數據" aria-label="Permalink to “第5步：在磁盤故障後檢查數據”">​</a></h3><p>12、我們的主要目的是，即使在任何磁盤故障或死機時必須保證數據是可用的。讓我們來看看，當任何一個磁盤不可用時會發生什麼。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Raid-Device-Verify.png" alt="Raid Device Verify"></p><p><em>驗證 RAID 設備</em></p><p>在上面的圖片中，我們可以看到在 RAID 中有2個設備是可用的，並且 Active Devices 是2。現在讓我們看看，當一個磁盤拔出（移除 sdc 磁盤）或損壞後會發生什麼。</p><pre><code># ls -l /dev | grep sd
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Test-RAID-Devices.png" alt="Test RAID Devices"></p><p><em>測試 RAID 設備</em></p><p>現在，在上面的圖片中你可以看到，一個磁盤不見了。我從虛擬機上刪除了一個磁盤。此時讓我們來檢查我們寶貴的數據。</p><pre><code># cd /mnt/raid1/
# cat tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Data.png" alt="Verify RAID Data"></p><p><em>驗證 RAID 數據</em></p><p>你可以看到我們的數據仍然可用。由此，我們可以瞭解 RAID 1（鏡像）的優勢。在接下來的文章中，我們將看到如何設置一個 RAID 5 條帶化分佈式奇偶校驗。希望這可以幫助你瞭解 RAID 1（鏡像）是如何工作的。</p><hr>`,78)),a("p",null,[e[3]||(e[3]=t("via: ",-1)),p(i,{href:"http://www.tecmint.com/create-raid1-in-linux/"},{default:n(()=>[...e[2]||(e[2]=[t("http://www.tecmint.com/create-raid1-in-linux/",-1)])]),_:1})]),a("p",null,[e[7]||(e[7]=t("作者：",-1)),p(i,{href:"http://www.tecmint.com/author/babinlonston/"},{default:n(()=>[...e[4]||(e[4]=[t("Babin Lonston",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),p(i,{href:"https://github.com/strugglingyouth"},{default:n(()=>[...e[5]||(e[5]=[t("strugglingyouth",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=t("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創翻譯，",-1)),p(i,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const f=r(c,[["render",l]]);export{h as __pageData,f as default};
